css.prototype:
/* Shared theme. Screen layout belongs to desktop.css or phone.css. */
:root {
  color-scheme: dark;
  font-family:
    system-ui,
    -apple-system,
    sans-serif;
  background: #0d1b14;
  color: #ecf1e7;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  overflow: hidden;
  touch-action: none;
}
button {
  font: inherit;
  color: inherit;
  border: 1px solid #71866d;
  border-radius: 8px;
  padding: 9px 11px;
  text-align: left;
  min-height: 40px;
}
button:focus-visible,
button.selected {
  outline: 3px solid #ebc875;
  outline-offset: 1px;
}
button:disabled {
  opacity: 0.5;
}
small {
  color: #c4cbbd;
  font-size: 10px;
}
h1 {
  font-size: 16px;
  margin: 8px 0;
}
h2 {
  font-size: 23px;
  margin: 0 0 10px;
}
#world {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
}
#hud {
  position: fixed;
  padding: 10px;
  pointer-events: auto;
  font-size: 13px;
  z-index: 6;
}
#hud button {
  margin: 2px 0;
  width: 100%;
  padding: 6px 9px;
  min-height: 34px;
}
#objective {
  font-size: 12px;
  line-height: 1.35;
  margin: 7px 0;
  color: #d5decc;
}
#location {
  font-weight: 700;
  margin-top: 7px;
}
#status {
  font-size: 11px;
}
#talent-button {
  border-color: #bda469;
  color: #f6e2a6;
  font-weight: 750;
}
#talent-button.talent-ready {
  border-color: #f0ca69;
  box-shadow:
    0 0 0 2px #d0a64f66,
    0 0 18px #d8aa4555;
}
#skills {
  position: fixed;
  display: grid;
  gap: 5px;
  z-index: 5;
}
#skills button {
  font-size: 16px;
  padding: 6px 4px;
  text-align: center;
  min-height: 49px;
}
#skills button.charging {
  border-color: #f0ca69;
  box-shadow:
    0 0 0 2px #d0a64f66,
    0 0 18px #d8aa4555;
  background: #4a422c;
}
#skills small {
  display: block;
  font-size: 9px;
}
#quick-items {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 5px;
}
#skills .potion-button {
  font-size: 12px;
  min-height: 42px;
}
#joystick {
  border-radius: 50%;
  position: relative;
  touch-action: none;
}
#stick {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}
#order-button,
#touch-interact-button {
  position: fixed;
  z-index: 12;
  text-align: center;
  font-weight: 750;
}
#modal {
  position: fixed;
  background: #15241af7;
  border: 1px solid #a2b495;
  border-radius: 12px;
  padding: 18px;
  overflow-y: auto;
  overflow-x: hidden;
  touch-action: pan-y;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  box-shadow: 8px 0 45px #0007;
  z-index: 10;
}
#modal[hidden],
[hidden] {
  display: none !important;
}
#modal-description {
  font-size: 13px;
  color: #cbd6c3;
  line-height: 1.5;
  white-space: pre-line;
  margin-bottom: 12px;
}
#modal-actions {
  display: grid;
  gap: 7px;
}
#modal-actions button {
  white-space: pre-line;
}
#modal-actions .detail {
  font-size: 11px;
  color: #b8c6ad;
  display: block;
  margin-top: 3px;
}
#close-button {
  margin: 14px 0;
  width: 100%;
}
#modal canvas {
  display: block;
  width: 100%;
  border: 1px solid #55714f;
  margin: 8px 0;
}
body.menu-open #skills {
  visibility: hidden;
}
.health {
  color: #9de39a;
}
.mana {
  color: #a1c9fa;
}
.gold {
  color: #f7da84;
}
#recall-button {
  color: #e7e2c3;
}
#target-button {
  position: relative;
  color: #f1deb0;
}
#target-button.has-target {
  border-color: #e7cb86;
  box-shadow:
    inset 0 1px #fff0bf30,
    0 0 0 1px #b4924870;
}
#target-button.target-pressing {
  box-shadow: inset 0 0 0 2px #dfc17b88;
}
#target-button.target-locked {
  border-color: #f3d38c;
  background: linear-gradient(160deg, #4c4531, #343d2d);
}
#target-button.target-locked::after {
  content: 'LOCK';
  position: absolute;
  top: -7px;
  right: 5px;
  font-size: 8px;
  letter-spacing: 0.07em;
  line-height: 1.2;
  padding: 1px 4px;
  border-radius: 3px;
  color: #f6e2aa;
  background: #233126;
  border: 1px solid #b99b58;
}

#desktop-hints {
  display: none;
}
/* A restrained ink, stone and brass layer over the existing prototype layout. */
button {
  background: linear-gradient(160deg, #344b3c, #25392f 58%, #213329);
  border-color: #879878a8;
  box-shadow:
    inset 0 1px #d8ddc01f,
    0 2px 6px #07120d88;
  text-shadow: 0 1px #0c1713;
}
button:hover {
  background: linear-gradient(160deg, #426249, #2d4836);
}
button.selected,
button:focus-visible {
  border-color: #f2d28b;
  background: linear-gradient(155deg, #496046, #304735);
  box-shadow:
    inset 3px 0 #edc77b,
    inset 0 1px #f5e9bf33,
    0 0 0 2px #72572e88;
}
button:disabled {
  background: #202c28;
  box-shadow: none;
  text-shadow: none;
}
#hud,
#modal,
#message {
  background: linear-gradient(145deg, #1d3027f5, #101f1bed 72%);
  border: 1px solid #9eaf8c9c;
  box-shadow:
    inset 0 1px #e8e6bf21,
    0 9px 28px #07120dcc;
}
#hud {
  border-radius: 12px;
}
#hud h1 {
  color: #f1deaa;
  letter-spacing: 0.025em;
  text-shadow: 0 2px 6px #0008;
  border-bottom: 1px solid #b2b68c55;
  padding-bottom: 8px;
}
#hud #menu-button {
  color: #f3d99c;
  border-color: #c5ac72a3;
}
#hero-stats {
  line-height: 1.35;
}
#hero-stats .hero-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 5px;
  color: #f2e9cb;
  font-weight: 750;
  margin: 3px 0 8px;
}
#hero-stats .hero-title small {
  letter-spacing: 0.09em;
  color: #d9c288;
}
.resource-line {
  display: block;
  margin: 5px 0 7px;
  font-size: 12px;
}
.resource-line span {
  display: block;
  margin-bottom: 3px;
}
.resource-line i {
  display: block;
  height: 6px;
  border: 1px solid #c8d0b347;
  border-radius: 8px;
  background: linear-gradient(to right, #88cc87 var(--fill), #314538 var(--fill));
  box-shadow: inset 0 1px 2px #06150d9c;
}
.resource-line.mana i {
  background: linear-gradient(to right, #89bce2 var(--fill), #2d4253 var(--fill));
}
#hero-stats .wallet {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  color: #c7d6bf;
  font-size: 11px;
  margin: 8px 0;
}
#hero-stats .restoring {
  display: block;
  color: #d7d6a0;
  margin: 3px 0;
}
#location {
  border-top: 1px solid #a7b69740;
  padding-top: 7px;
  color: #f0d695;
}
#objective {
  border-left: 2px solid #c5ae72;
  padding-left: 8px;
}
#status {
  color: #e2bd94;
}
#skills button {
  border-color: #91a58d9c;
  background: linear-gradient(155deg, #3c5546, #24372e);
  box-shadow:
    inset 0 1px #e8eacc24,
    0 3px 8px #07120cbb;
  color: #f6ecd1;
  font-weight: 650;
}
#skills button small {
  font-weight: 500;
  color: #d7d9b8;
}
#skills .locked {
  background: linear-gradient(155deg, #28332d, #1d2924);
  color: #9fa99b;
}
#skills .potion-button {
  background: linear-gradient(155deg, #42605c, #2b403e);
  border-color: #9bb8a7a8;
}
#joystick {
  background: radial-gradient(circle at 45% 40%, #42634bba 0 22%, #243d30cc 24% 53%, #101f1be6 80%);
  border: 3px solid #bed0a5;
  box-shadow:
    inset 0 0 0 7px #57746166,
    0 5px 15px #08150da8;
}
#stick {
  background: radial-gradient(circle at 35% 30%, #b8d0a0, #6f9676 70%, #4f785e);
  border: 2px solid #d2d8b4;
  box-shadow: 0 3px 9px #07180eaa;
}
#order-button {
  border-color: #e8ca8d;
  color: #fce9bb;
  background: linear-gradient(155deg, #69563b, #3e392d);
  font-weight: 750;
  text-align: center;
  box-shadow:
    inset 0 1px #f5dfac66,
    0 3px 12px #07120dcc;
}
#modal {
  border-color: #c6bb92;
  border-radius: 14px;
}
#modal h2 {
  color: #f0d99b;
  letter-spacing: 0.015em;
  border-bottom: 1px solid #bac7a14d;
  padding-bottom: 10px;
}
#modal-description {
  color: #d9e0cd;
}
#modal-actions button {
  border-left: 3px solid #829d82;
}
#modal-actions button.selected {
  border-left-color: #f3d17d;
}
#modal-actions .detail {
  color: #c1cdb4;
}
#close-button {
  border-color: #d1b876;
  color: #f2d59a;
}
#message {
  border-color: #abb99772;
  color: #f2ecd7;
  border-radius: 9px;
}
/* v0.8.32 critical notices: rare, readable, top-center only. */
#message {
  display: block !important;
  position: fixed;
  left: 50%;
  right: auto;
  top: max(12px, env(safe-area-inset-top));
  bottom: auto;
  width: min(520px, calc(100vw - 24px));
  padding: 10px 16px;
  transform: translate(-50%, -10px);
  opacity: 0;
  visibility: hidden;
  background: linear-gradient(155deg, #f0c96e, #d7a94c);
  color: #241b0c;
  border: 2px solid #fff0b4;
  border-radius: 10px;
  box-shadow:
    0 4px 18px #0009,
    inset 0 1px #fff7d399;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.3;
  text-align: center;
  letter-spacing: 0.01em;
  pointer-events: none;
  z-index: 20;
  transition:
    opacity 0.35s ease,
    transform 0.35s ease,
    visibility 0.35s;
}
#message.visible {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

@media (prefers-reduced-motion: reduce) {
  #message {
    transition: none;
  }
}
/* Game gestures must not become text selection or iOS touch callouts. */
body {
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}
input,
textarea,
[contenteditable='true'] {
  -webkit-user-select: text;
  user-select: text;
  -webkit-touch-callout: default;
}
#location {
  display: none;
}

/* Compact adventure interface: slate, brass and restrained contrast. */
:root {
  --ui-ink: #eef3f2;
  --ui-muted: #b7c8ce;
  --ui-brass: #e1be78;
  --ui-edge: #7c99a488;
}
button {
  background: linear-gradient(155deg, #293e4a, #182a35);
  color: var(--ui-ink);
  border-color: var(--ui-edge);
  border-radius: 9px;
  box-shadow:
    inset 0 1px #e5f6ff17,
    0 2px 8px #06101988;
  text-shadow: none;
}
button:hover {
  background: linear-gradient(155deg, #345363, #223743);
}
button.selected,
button:focus-visible {
  background: linear-gradient(155deg, #455968, #293c47);
  border-color: var(--ui-brass);
  box-shadow:
    inset 3px 0 #e1be78,
    0 0 0 2px #b18c4b77;
}
#hud,
#modal {
  background: linear-gradient(155deg, #172b36f5, #0e1c26f2);
  border-color: var(--ui-edge);
  box-shadow:
    inset 0 1px #d7eef225,
    0 8px 28px #050d16b0;
  backdrop-filter: blur(8px);
}
#hud h1 {
  display: none;
}
#hero-stats .hero-title {
  margin: 0 0 5px;
  font-size: 12px;
  color: #f1e5c7;
}
#hero-stats .hero-title small {
  color: var(--ui-brass);
  letter-spacing: 0.035em;
}
.resource-line {
  margin: 3px 0 5px;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.resource-line span {
  margin-bottom: 3px;
  color: #e8eff1;
}
.resource-line i {
  height: 5px;
  border-color: #afc6d044;
  background: linear-gradient(to right, #76bf92 var(--fill), #304a43 var(--fill));
}
.resource-line.mana i {
  background: linear-gradient(to right, #76bfe5 var(--fill), #284452 var(--fill));
}
#hero-stats .wallet {
  margin: 6px 0 2px;
  font-size: 10px;
  color: var(--ui-muted);
  font-variant-numeric: tabular-nums;
}
#objective {
  border-left: 0;
  border-top: 1px solid #95adbb35;
  padding: 6px 0 0;
  margin: 5px 0 0;
  font-size: 10px;
  line-height: 1.3;
  color: var(--ui-muted);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}
#status {
  color: #e1bc91;
}
#hud #menu-button,
#talent-button,
#close-button {
  color: #f0d398;
  border-color: #baa16c9c;
}
#modal {
  display: flex;
  flex-direction: column;
  border-radius: 13px;
  padding: 14px;
  overflow: hidden;
}
#modal h2 {
  flex: 0 0 auto;
  font-size: 18px;
  line-height: 1.2;
  color: #efdaaa;
  padding-bottom: 8px;
  margin-bottom: 9px;
}
#modal-content {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  touch-action: pan-y;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-color: #668590 #132833;
  scrollbar-width: thin;
}
#modal-description {
  margin: 0 0 9px;
  font-size: 12px;
  line-height: 1.45;
  color: #cedde0;
}
#modal-actions {
  gap: 5px;
}
#modal-actions button {
  min-height: 40px;
  padding: 8px 10px;
  font-size: 12px;
  line-height: 1.3;
  border-left-color: #6e99a7;
}
#modal-actions button.selected {
  border-left-color: var(--ui-brass);
}
#modal-actions .detail {
  font-size: 10px;
  line-height: 1.4;
  margin-top: 3px;
  color: var(--ui-muted);
}
#close-button {
  flex: 0 0 auto;
  min-height: 40px;
  margin: 10px 0 0;
  padding: 7px 10px;
  text-align: center;
}
#skills button {
  background: linear-gradient(155deg, #334e59, #1c303e);
  border-color: #81a1a89c;
}
#skills .potion-button {
  background: linear-gradient(155deg, #365a56, #233e42);
}
#message {
  width: min(380px, calc(100vw - 24px));
  padding: 8px 11px;
  font-size: 12px;
  border-width: 1px;
  border-radius: 9px;
}

body.menu-open::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 9;
  background: #030c1591;
  pointer-events: none;
}

css.desktop:
/* Keyboard-first browser presentation, including touch-capable Chromebooks. */
body[data-experience='desktop'] #hud {
  right: 12px;
  top: 12px;
  width: min(260px, 27vw);
  max-height: calc(100vh - 24px);
  overflow: auto;
}
body[data-experience='desktop'] #movement {
  display: none;
}
body[data-experience='desktop'] #skills {
  left: calc((100vw - min(260px, 27vw) - 24px) / 2);
  bottom: 14px;
  transform: translateX(-50%);
  width: min(820px, calc(100vw - 300px));
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: 6px;
  padding: 8px;
  background: #102018eb;
  border: 1px solid #9eaf8c77;
  border-radius: 12px;
}
body[data-experience='desktop'] #quick-items {
  grid-column: span 2;
}
body[data-experience='desktop'] #skills button {
  min-width: 0;
  min-height: 48px;
}
body[data-experience='desktop'] #desktop-hints {
  display: block;
  position: fixed;
  left: 12px;
  bottom: 92px;
  max-width: calc(100vw - 300px);
  font-size: 11px;
  color: #d9d2b4;
  background: #102018cc;
  padding: 7px 10px;
  border-radius: 7px;
  pointer-events: none;
}
body[data-experience='desktop'] #modal {
  top: 24px;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  width: min(640px, calc(100vw - 48px));
  padding: 24px;
}
body[data-experience='desktop'] #world,
body[data-experience='desktop'] button {
  pointer-events: auto;
  cursor: pointer;
}
body[data-experience='desktop'].menu-open #desktop-hints {
  display: none;
}
@media (max-width: 1000px) {
  body[data-experience='desktop'] #hud {
    width: 220px;
    font-size: 11px;
  }
  body[data-experience='desktop'] #skills {
    left: calc((100vw - 244px) / 2);
    width: calc(100vw - 260px);
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  body[data-experience='desktop'] #desktop-hints {
    bottom: 144px;
    max-width: calc(100vw - 260px);
  }
}
@media (max-height: 640px) {
  body[data-experience='desktop'] #hud h1 {
    display: none;
  }
  body[data-experience='desktop'] #hud button {
    min-height: 28px;
  }
  body[data-experience='desktop'] .resource-line {
    margin: 3px 0;
  }
}

body[data-experience='desktop'] #world {
  cursor: default;
}

/* Desktop: an information dock, not a permanent sidebar. */
body[data-experience='desktop'] #hud {
  right: 10px;
  top: 10px;
  width: 214px;
  max-height: calc(100dvh - 20px);
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 5px;
  padding: 9px;
  font-size: 11px;
}
body[data-experience='desktop'] #hud button {
  min-width: 0;
  min-height: 32px;
  width: 100%;
  margin: 0;
  padding: 5px 6px;
  font-size: 11px;
  text-align: center;
}
body[data-experience='desktop'] #hud #menu-button,
body[data-experience='desktop'] #hero-stats,
body[data-experience='desktop'] #objective,
body[data-experience='desktop'] #status,
body[data-experience='desktop'] #squad-button,
body[data-experience='desktop'] #talent-button {
  grid-column: 1 / -1;
}
body[data-experience='desktop'] #talent-button:not(.talent-ready) {
  display: none;
}
body[data-experience='desktop'] #hero-stats .wallet {
  margin: 5px 0 1px;
}
body[data-experience='desktop'] #desktop-hints {
  display: none;
}
body[data-experience='desktop'] #skills {
  left: calc((100vw - 238px) / 2);
  width: min(780px, calc(100vw - 254px));
}
body[data-experience='desktop'] #modal {
  top: 50%;
  bottom: auto;
  left: 50%;
  width: min(430px, calc(100vw - 32px));
  max-height: min(72dvh, 650px);
  padding: 16px;
  transform: translate(-50%, -50%);
}
@media (max-width: 1000px) {
  body[data-experience='desktop'] #hud {
    width: 204px;
  }
  body[data-experience='desktop'] #skills {
    left: calc((100vw - 228px) / 2);
    width: calc(100vw - 244px);
  }
}

css.phone:
/* Phone gameplay keeps the world visible and combat within thumb reach. */
body[data-experience='phone'] #hud {
  left: max(8px, env(safe-area-inset-left));
  right: max(8px, env(safe-area-inset-right));
  top: max(8px, env(safe-area-inset-top));
  width: auto;
  padding: 5px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 44px;
  gap: 8px;
  align-items: center;
  font-size: 11px;
  background: #102018b8;
  box-shadow: none;
  border-color: #9eaf8c55;
}
body[data-experience='phone'] #hud h1,
body[data-experience='phone'] #objective,
body[data-experience='phone'] #talent-button {
  display: none;
}
body[data-experience='phone'] #hud #menu-button {
  grid-column: 2;
  grid-row: 1;
  margin: 0;
  padding: 4px;
  min-height: 44px;
  width: 44px;
  text-align: center;
  font-size: 11px;
}
body[data-experience='phone'] #menu-button small {
  display: none;
}
body[data-experience='phone'] #hero-stats {
  grid-column: 1;
  grid-row: 1;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px 8px;
  line-height: 1.1;
}
body[data-experience='phone'] #hero-stats .hero-title {
  grid-column: 1/-1;
  margin: 0;
  font-size: 10px;
  justify-content: flex-start;
}
body[data-experience='phone'] #hero-stats .hero-title > span,
body[data-experience='phone'] #hero-stats .wallet,
body[data-experience='phone'] #hero-stats .restoring {
  display: none;
}
body[data-experience='phone'] #hero-stats .hero-title small {
  font-size: 9px;
}
body[data-experience='phone'] .resource-line {
  margin: 1px 0;
  font-size: 11px;
}
body[data-experience='phone'] .resource-line span {
  margin-bottom: 2px;
}
body[data-experience='phone'] .resource-line i {
  height: 5px;
}
body[data-experience='phone'] #status {
  position: fixed;
  top: calc(max(8px, env(safe-area-inset-top)) + 62px);
  left: 50%;
  transform: translateX(-50%);
  max-width: calc(100vw - 24px);
  padding: 5px 8px;
  border-radius: 6px;
  background: #102018e8;
  font-size: 11px;
  line-height: 1.25;
  pointer-events: none;
}
body[data-experience='phone'] #status:empty {
  display: none;
}
body[data-experience='phone'] #movement {
  position: fixed;
  left: max(8px, env(safe-area-inset-left));
  bottom: max(8px, env(safe-area-inset-bottom));
  z-index: 5;
}
body[data-experience='phone'] #joystick {
  width: 104px;
  height: 104px;
  pointer-events: auto;
}
body[data-experience='phone'] #stick {
  width: 44px;
  height: 44px;
  left: 27px;
  top: 27px;
}
body[data-experience='phone'] #skills {
  left: auto;
  right: max(8px, env(safe-area-inset-right));
  bottom: max(8px, env(safe-area-inset-bottom));
  width: min(184px, calc(50vw - 12px));
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
body[data-experience='phone'] #skills button {
  min-width: 0;
  min-height: 52px;
  font-size: 13px;
  padding: 6px 4px;
  touch-action: none;
  pointer-events: auto;
}
body[data-experience='phone'] #skills > button.locked {
  display: none;
}
body[data-experience='phone'] #skills .skill-ready small,
body[data-experience='phone'] #skills .key-hint {
  display: none;
}
body[data-experience='phone'] #quick-items {
  grid-column: 1/-1;
  gap: 6px;
}
body[data-experience='phone'] #quick-items:not(:has(button:not([hidden]))) {
  display: none;
}
body[data-experience='phone'] #skills .potion-button {
  min-height: 48px;
  font-size: 11px;
}
body[data-experience='phone'] #recall-button,
body[data-experience='phone'] #target-button {
  position: fixed;
  bottom: calc(124px + env(safe-area-inset-bottom));
  min-height: 44px;
  margin: 0;
  padding: 6px 4px;
  font-size: 11px;
  text-align: center;
  z-index: 6;
}
body[data-experience='phone'] #recall-button {
  left: max(8px, env(safe-area-inset-left));
  width: 90px;
}
body[data-experience='phone'] #target-button {
  left: calc(max(8px, env(safe-area-inset-left)) + 98px);
  width: 76px;
}
body[data-experience='phone'] #recall-button small,
body[data-experience='phone'] #target-button small {
  display: none;
}
body[data-experience='phone'] #squad-button {
  position: fixed;
  left: max(8px, env(safe-area-inset-left));
  bottom: calc(176px + env(safe-area-inset-bottom));
  width: 104px;
  min-height: 44px;
  margin: 0;
  font-size: 11px;
  z-index: 6;
}
body[data-experience='phone'] #touch-interact-button {
  left: 50%;
  right: auto;
  top: max(68px, 17vh);
  bottom: auto;
  transform: translateX(-50%);
  width: 104px;
  min-height: 44px;
  font-size: 12px;
  padding: 8px 6px;
  touch-action: manipulation;
  border-color: #e8ca8d;
  color: #fce9bb;
  background: linear-gradient(155deg, #69563b, #3e392d);
}
body[data-experience='phone'] #order-button {
  right: max(8px, env(safe-area-inset-right));
  bottom: max(8px, env(safe-area-inset-bottom));
  width: 96px;
  min-height: 52px;
  display: none;
}
body[data-experience='phone'].menu-open #order-button {
  display: block;
}
body[data-experience='phone'].menu-open #touch-interact-button {
  display: none;
}
body[data-experience='phone'].menu-open #movement {
  z-index: 11;
}
body[data-experience='phone'] #modal {
  top: max(8px, env(safe-area-inset-top));
  right: max(8px, env(safe-area-inset-right));
  width: calc(100vw - max(8px, env(safe-area-inset-left)) - max(8px, env(safe-area-inset-right)));
  bottom: 124px;
  padding: 12px;
}
body[data-experience='phone'] #modal-actions button {
  min-height: 48px;
  pointer-events: auto;
}
body[data-experience='phone'] #message {
  width: min(420px, calc(100vw - 16px));
  font-size: 12px;
  padding: 9px 12px;
  top: max(8px, env(safe-area-inset-top));
}
/* The optional historical layout keeps combat above the left joystick. */
body[data-experience='phone'][data-phone-layout='left-hand'] #skills {
  right: auto;
  left: max(8px, env(safe-area-inset-left));
  bottom: calc(124px + env(safe-area-inset-bottom));
}
body[data-experience='phone'][data-phone-layout='left-hand'] #recall-button {
  left: auto;
  right: max(8px, env(safe-area-inset-right));
  bottom: max(8px, env(safe-area-inset-bottom));
}
body[data-experience='phone'][data-phone-layout='left-hand'] #target-button {
  left: auto;
  right: calc(max(8px, env(safe-area-inset-right)) + 98px);
  bottom: max(8px, env(safe-area-inset-bottom));
}
body[data-experience='phone'][data-phone-layout='left-hand'] #squad-button {
  left: auto;
  right: max(8px, env(safe-area-inset-right));
  bottom: calc(60px + env(safe-area-inset-bottom));
}
@media (max-height: 500px) and (min-width: 480px) {
  body[data-experience='phone'] #hud {
    right: auto;
    width: min(360px, 48vw);
  }
  body[data-experience='phone'] #touch-interact-button {
    left: calc(50vw - 80px);
    top: 50vh;
  }
  body[data-experience='phone'] #skills {
    width: min(340px, 48vw);
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  body[data-experience='phone'] #skills button {
    min-height: 50px;
    padding: 5px 4px;
  }
  body[data-experience='phone'] #modal {
    top: 8px;
    width: min(520px, 62vw);
    bottom: 120px;
  }
  body[data-experience='phone'][data-phone-layout='left-hand'] #skills {
    bottom: 122px;
  }
}

/* Phone: show HP, MP, class and level without a full-width banner. */
body[data-experience='phone'] #hud {
  left: max(8px, env(safe-area-inset-left));
  right: auto;
  width: min(310px, calc(100vw - 16px));
  padding: 6px 7px;
  grid-template-columns: minmax(0, 1fr) 42px;
  gap: 6px;
  border-radius: 10px;
  background: linear-gradient(155deg, #172b36ec, #10212bde);
}
body[data-experience='phone'] #hero-stats {
  gap: 2px 7px;
}
body[data-experience='phone'] #hero-stats .hero-title {
  margin: 0 0 1px;
  justify-content: space-between;
  font-size: 11px;
}
body[data-experience='phone'] #hero-stats .hero-title > span {
  display: inline;
}
body[data-experience='phone'] #hero-stats .hero-title small {
  font-size: 10px;
}
body[data-experience='phone'] .resource-line {
  margin: 1px 0;
  font-size: 10px;
}
body[data-experience='phone'] .resource-line i {
  height: 5px;
}
body[data-experience='phone'] #hud #menu-button {
  width: 42px;
  min-height: 42px;
  padding: 4px;
  font-size: 0;
}
body[data-experience='phone'] #hud #menu-button::before {
  content: '☰';
  display: inline-block;
  font-size: 20px;
  line-height: 1;
}
body[data-experience='phone'] #status {
  top: calc(max(8px, env(safe-area-inset-top)) + 59px);
  width: max-content;
  max-width: min(270px, calc(100vw - 24px));
  padding: 5px 8px;
  background: #122733e8;
  border: 1px solid #7996a54d;
}
body[data-experience='phone'] #modal {
  top: 45%;
  bottom: auto;
  right: auto;
  left: 50%;
  width: min(330px, calc(100vw - 24px));
  max-height: min(54dvh, 470px);
  padding: 11px;
  transform: translate(-50%, -50%);
}
body[data-experience='phone'] #modal h2 {
  font-size: 17px;
}
body[data-experience='phone'] #modal-actions button,
body[data-experience='phone'] #close-button {
  min-height: 44px;
}
body[data-experience='phone'] #message {
  width: min(310px, calc(100vw - 20px));
  padding: 7px 10px;
  font-size: 11px;
}
@media (max-height: 500px) and (min-width: 480px) {
  body[data-experience='phone'] #hud {
    width: min(310px, 44vw);
  }
  body[data-experience='phone'] #modal {
    top: 46%;
    width: min(390px, 58vw);
    max-height: min(60dvh, 270px);
  }
}
